def _data_file():
    # در نسخه exe (PyInstaller onefile)، مسیر __file__ داخل پوشه موقت است و با
    # بسته شدن برنامه پاک می‌شود؛ پس تنظیمات را در LOCALAPPDATA نگه می‌داریم.
    if getattr(sys, "frozen", False):
        _base = Path(os.environ.get("LOCALAPPDATA", str(Path.home()))) / "StreamScanner"
        try:
            _base.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        return _base / "servers.json"
    return Path(__file__).resolve().parent / "servers.json"


